# For each demo: does target have a value that NO OTHER window has (a "unique" property)?
for nm,(ii,oo) in enumerate(pairs,1):
    H,W=len(ii),len(ii[0])
    pos={}
    for a in range(H-n+1):
        for b in range(W-n+1):
            w=[rr[b:b+n] for rr in ii[a:a+n]]
            pos[(a,b)]=w
    tgt=pos[(next((k for k,v in pos.items() if v==oo)[0]) or 'x')]
    vals={(a,b,tuple(tuple(r) for r in p)) for a,b,p in pos.items()}
    # find scalar features where target is the sole argmax/argmin across ALL windows of that demo
    feats={
     'sum':lambda p: sum(x for r in p for x in r),
     'ndist':lambda p: len({x for r in p for x in r}),
     'sym':lambda p: sum(1 for i in range(n) for j in range(i+1,n) if p[i][j]==p[j][i]),
     'diagprod':lambda p: abs(p[0][0]*p[1][1]*p[2][2]*p[3][3]),
     'diagsum':lambda p: abs(sum(p[i][i] for i in range(n))),
     'anti':lambda p: abs(sum(p[i][n-1-i] for i in range(n))),
     'mincnt':lambda p: min(collections.Counter(x for r in p for x in r).values()),
     'maxcnt':lambda p: max(collections.Counter(x for r in p for x in r).values()),
     'modecount':lambda p: max(collections.Counter(x for r in p for x in r).values()),
     'minval':lambda p: min(x for r in p for x in r),
     'maxval':lambda p: max(x for r in p for x in r),
     'zeros':lambda p: sum(1 for r in p for x in r if x==0),
     }
    found=[]
    for fn,f in feats.items():
        vals=[f(v) for v in pos.values()]
        tg=f(tgt)
        if tg==max(vals) and vals.count(tg)==1: found.append('MAX'+fn)
        if tg==min(vals) and vals.count(tg)==1: found.append('MIN'+fn)
